insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_126'
from (values
('127.873.d.1.A',3,'A service writer greets a customer, listens to the description of a rattling noise and repeats it back before writing the ticket. She is demonstrating:','["effective oral communication with customers and coworkers", "avoiding the customer", "interrupting the customer", "using only slang"]'::jsonb,0,'Listen, confirm, record.','original'),
('127.873.d.1.A',4,'When explaining a repair to a customer with no mechanical background, a technician should:','["avoid eye contact", "use plain language and avoid unexplained jargon", "use only technical terms", "speak quickly"]'::jsonb,1,'Match the explanation to the listener.','original'),
('127.873.d.1.B',3,'A technician writes on a repair order exactly what she found, what she replaced and the test results. This shows effective:','["vague notes", "avoiding documentation", "written communication with others in the shop", "guessing"]'::jsonb,2,'Clear repair notes help everyone.','original'),
('127.873.d.1.B',4,'A well-written repair note for a coolant leak should include:','["a joke", "only the word ''fixed''", "the customer''s favorite color", "the location of the leak, the part replaced and the pressure test result"]'::jsonb,3,'Specific, complete notes.','original'),
('127.873.d.1.C',3,'A technician adds the cost of a $42.50 sensor, $18.75 in fluids and $60 in labor to prepare an estimate. She is demonstrating:','["mathematical skills in addition for a repair estimate", "ignoring costs", "avoiding math", "guessing"]'::jsonb,0,'42.50 + 18.75 + 60 = 121.25.','original'),
('127.873.d.1.C',4,'A shop charges $85 per hour and a job takes 2.5 hours. The labor cost is:','["$170.00", "$212.50", "$235.00", "$187.50"]'::jsonb,1,'85 × 2.5 = 212.50.','original'),
('127.873.d.2.A',3,'A technician looks up a wiring diagram and the manufacturer''s recommended service interval in the service manual before repairing a lighting circuit. She is:','["guessing", "skipping the manual", "locating, reading and interpreting transportation repair and service information", "using only memory"]'::jsonb,2,'Use service information.','original'),
('127.873.d.2.A',4,'If a technician''s memory conflicts with the printed torque value in the service manual, she should:','["ignore the manual", "guess an average", "use the larger number", "follow the manufacturer''s published specification"]'::jsonb,3,'Specs come from the manual.','original'),
('127.873.d.2.B',3,'A student learns about hybrid drive systems, driver-assist sensors and electric vehicle charging in a transportation class. She is describing:','["basic and emerging transportation technologies", "only paper maps", "unrelated hobbies", "ancient tools only"]'::jsonb,0,'Emerging tech is part of the field.','original'),
('127.873.d.2.B',4,'Which is an emerging technology that technicians must now understand?','["crank-start engines", "high-voltage battery systems in electric vehicles", "horse carriages", "hand-cranked windows only"]'::jsonb,1,'EV systems are emerging tech.','original'),
('127.873.d.3.A',3,'Before using an impact wrench on lug nuts, a technician wears eye protection, selects the right socket and checks the air line. She is demonstrating:','["ignoring rules", "unsafe habits", "awareness of the proper way to safely use hand and power tools", "careless setup"]'::jsonb,2,'Use tools safely.','original'),
('127.873.d.3.A',4,'The correct way to store a power drill after use is to:','["leave it plugged in on the floor", "drop it", "hide it under a bench", "unplug or disconnect it and put it away in its place"]'::jsonb,3,'Safe storage prevents accidents.','original'),
('127.873.d.3.B',3,'A technician plugs a scan tool into a car''s data port and reads trouble codes from the computer. She is identifying:','["diagnostic tools and equipment", "decorations", "hand tools only", "only cleaning tools"]'::jsonb,0,'Scan tools are diagnostic tools.','original'),
('127.873.d.3.B',4,'A digital multimeter is used in a shop to:','["weigh parts", "measure voltage, resistance and current in circuits", "tighten bolts", "measure tire tread only"]'::jsonb,1,'Meters test electrical circuits.','original'),
('127.873.d.3.C',3,'A technician picks a torque wrench to tighten a wheel''s lug nuts to the specified value. She is:','["skipping the spec", "using a chisel", "identifying a hand tool and describing its proper use", "guessing the tool"]'::jsonb,2,'Torque wrenches apply measured force.','original'),
('127.873.d.3.C',4,'A flare-nut wrench is best used on a brake line fitting because it:','["is longer", "slides off easily", "is cheaper", "grips more of the fitting and reduces rounding"]'::jsonb,3,'Flare-nut wrenches protect soft fittings.','original'),
('127.874.d.1.A',3,'A small-engine technician refuses to sell a customer a used mower with a known cracked deck without disclosing the defect. He is showing:','["ethical and legal responsibilities appropriate to the career", "avoiding disclosure", "dishonesty", "ignoring the law"]'::jsonb,0,'Be honest about defects.','original'),
('127.874.d.1.A',4,'Which action best shows legal responsibility when disposing of old engine oil from a customer''s mower?','["dumping it on the lawn", "taking it to an approved recycling collection point", "pouring it down a drain", "burning it"]'::jsonb,1,'Follow disposal laws.','original'),
('127.874.d.1.B',3,'A new hire at a repair shop greets customers politely, arrives on time and helps clean the bay. He is demonstrating:','["carelessness", "lateness", "proper etiquette and behavior", "rude habits"]'::jsonb,2,'Courtesy and reliability matter.','original'),
('127.874.d.1.B',4,'A customer complains angrily about a delay. The technician should respond by:','["walking away", "ignoring them", "arguing", "listening calmly and explaining the next steps"]'::jsonb,3,'Stay professional.','original'),
('127.874.d.1.C',3,'A technician tucks in his shirt, ties back his hair and washes his hands before meeting a customer. This shows appropriate:','["personal appearance and hygiene", "careless dress", "a messy appearance", "poor hygiene"]'::jsonb,0,'Professional appearance.','original'),
('127.874.d.1.C',4,'In a small-engine shop, loose clothing and hanging jewelry should be avoided because they can:','["improve safety", "get caught in moving parts", "reduce noise", "save time"]'::jsonb,1,'Prevent entanglement.','original'),
('127.874.d.1.D',3,'A student writes an email to a parts supplier asking for a price and then listens carefully to a coworker''s instructions on a phone call. He is practicing:','["confusion", "avoidance", "written and oral communication and effective listening", "silence"]'::jsonb,2,'Writing and listening skills.','original'),
('127.874.d.1.D',4,'Which habit shows effective listening when a supervisor explains a repair schedule?','["interrupting", "texting", "looking away", "taking notes and asking clarifying questions"]'::jsonb,3,'Active listening.','original'),
('127.874.d.1.E',3,'A student reads the engine manual and writes a clear step-by-step procedure for changing spark plugs, including torque values and warnings. He is employing:','["technical writing and preparation skills", "jokes", "random notes", "guesses"]'::jsonb,0,'Technical writing is precise.','original'),
('127.874.d.1.E',4,'A good technical procedure includes steps that are:','["hidden", "numbered, specific and in the right order", "unordered", "vague"]'::jsonb,1,'Order and clarity matter.','original'),
('127.874.d.1.F',3,'A student explains the four strokes of an engine to the class using a diagram, speaking clearly without notes. He is demonstrating:','["silence", "reading silently", "effective speaking skills through prepared and extemporaneous presentations", "mumbling"]'::jsonb,2,'Speak clearly and confidently.','original'),
('127.874.d.1.F',4,'An extemporaneous speech is one that is:','["read word for word", "memorized exactly", "silent", "delivered with little advance preparation or script"]'::jsonb,3,'Extemporaneous means impromptu.','original'),
('127.874.d.2.A',3,'A shop begins servicing battery-powered string trimmers and robotic mowers alongside gasoline equipment. This shows how:','["emerging technologies affect the small engine technology industry", "technology has no effect", "shops never change", "only old tools matter"]'::jsonb,0,'New tech changes the trade.','original'),
('127.874.d.2.A',4,'Which emerging technology is changing outdoor power equipment?','["steam engines", "lithium-ion battery power and electronic controls", "sail power", "hand cranks"]'::jsonb,1,'Battery tools are growing.','original'),
('127.874.d.2.B',3,'A business owner worries about a shortage of trained technicians and rising parts costs. These are:','["weather only", "unrelated topics", "issues affecting the small engine technology industry", "decorations"]'::jsonb,2,'Labor and cost issues.','original'),
('127.874.d.2.B',4,'A growing environmental concern for small engines is:','["silent operation", "too many batteries", "lack of fuel", "exhaust emissions from older two-stroke engines"]'::jsonb,3,'Emissions rules affect small engines.','original'),
('127.874.d.2.C',3,'A shop learns that EPA rules limit emissions from small off-road engines and updates its repair procedures. This is:','["discussing regulations and laws and their impact on the industry", "avoiding updates", "breaking rules", "ignoring laws"]'::jsonb,0,'Comply with emission laws.','original'),
('127.874.d.2.C',4,'A technician who removes an emissions control component from a mower engine may be:','["improving legality", "violating federal law and causing fines", "following the law", "saving money legally"]'::jsonb,1,'Tampering is illegal.','original'),
('127.874.d.2.D',3,'A technician subscribes to an outdoor power equipment magazine and reads about a new carburetor recall. He is:','["avoiding news", "skipping reading", "reading written material to stay abreast of current industry issues", "ignoring trends"]'::jsonb,2,'Read to stay current.','original'),
('127.874.d.2.D',4,'Reading manufacturer service bulletins regularly helps a technician to:','["avoid training", "skip inspections", "ignore customers", "learn about known problems and updated repair procedures"]'::jsonb,3,'Bulletins carry updates.','original'),
('127.874.d.3.A',3,'A student joins a career and technical student organization and helps plan a leadership workshop and a skills contest. She is participating in:','["the planning and development of leadership and skill development activities", "avoiding teamwork", "ignoring opportunities", "skipping meetings"]'::jsonb,0,'CTSOs build leadership.','original'),
('127.874.d.3.A',4,'A skills contest in a small-engine class helps a student to:','["skip safety", "practice technical skills under timed conditions and receive feedback", "avoid learning", "reduce teamwork"]'::jsonb,1,'Contests build skills.','original'),
('127.874.d.3.B',3,'A student uses the career and technical student organization''s scholarship list, mentor network and competitive events to plan her future. She is:','["avoiding support", "wasting resources", "using resources available through a student organization", "ignoring help"]'::jsonb,2,'Use organization resources.','original'),
('127.874.d.3.B',4,'Which resource from a career and technical student organization could help a student find industry contacts?','["a lunch menu", "a parking pass", "a vending machine", "its networking events and mentor program"]'::jsonb,3,'Networking events connect students.','original'),
('127.874.d.4.A',3,'A shop posts a monthly checklist for inspecting the lifts, cleaning the parts washer and checking fire extinguishers. This is a:','["preventative maintenance schedule plan for the facility", "random chore list", "vacation plan", "sales plan"]'::jsonb,0,'Schedule routine facility checks.','original'),
('127.874.d.4.A',4,'A preventative maintenance schedule differs from a repair-only approach because it:','["waits for breakdowns", "performs service before problems occur", "ignores the schedule", "skips inspection"]'::jsonb,1,'PM is proactive.','original'),
('127.874.d.4.B',3,'A technician follows the shop''s schedule to sharpen mower blades, calibrate the torque wrench and oil the bench grinder. He is using:','["no schedule", "random work", "the preventative maintenance schedule for tools and equipment", "guesswork"]'::jsonb,2,'Maintain tools on schedule.','original'),
('127.874.d.4.B',4,'A torque wrench that is not recalibrated on schedule may give:','["faster repairs", "perfect results", "shorter wait times", "inaccurate readings and cause over- or under-tightened bolts"]'::jsonb,3,'Calibration keeps accuracy.','original'),
('127.874.d.4.C',3,'After servicing a chainsaw, a technician completes the repair order with the customer''s name, the work performed and the parts used. He is completing:','["repair orders and paperwork related to small engine work", "losing data", "hiding steps", "avoiding paperwork"]'::jsonb,0,'Document every repair.','original'),
('127.874.d.4.C',4,'The repair order is important for a shop because it:','["slows work", "documents the work done and supports billing and warranty claims", "hides costs", "avoids records"]'::jsonb,1,'Orders support billing and warranty.','original'),
('127.874.d.4.D',3,'A technician totals the price of a new carburetor kit, a fuel filter and 1.5 hours of labor to give a customer a quote. He is:','["hiding fees", "guessing", "estimating parts and labor costs on a repair order", "avoiding quotes"]'::jsonb,2,'Estimate parts plus labor.','original'),
('127.874.d.4.D',4,'A job needs $24 in parts and 2 hours of labor at $60 per hour. The estimate is:','["$204", "$84", "$120", "$144"]'::jsonb,3,'24 + 120 = 144.','original'),
('127.874.d.4.E',3,'A technician looks up the valve clearance specification and the exploded parts diagram in the engine service manual. She is:','["locating and interpreting service and repair information", "skipping the manual", "using memory only", "guessing"]'::jsonb,0,'Use the service manual.','original'),
('127.874.d.4.E',4,'A parts breakdown (exploded view) is most useful for:','["setting pay", "identifying part names and numbers and seeing how pieces fit together", "choosing paint", "scheduling shifts"]'::jsonb,1,'Exploded views show assembly.','original'),
('127.874.d.5.A',3,'A student writes a proposal to build a small go-kart for the school''s engine lab, listing goals, materials and a budget. She is:','["avoiding planning", "skipping steps", "developing a project proposal", "ignoring costs"]'::jsonb,2,'Proposals state goal and budget.','original'),
('127.874.d.5.A',4,'A project proposal for a lab build should state:','["only a drawing", "only a title", "no details", "the purpose, needed parts, cost and a schedule"]'::jsonb,3,'Proposals are complete.','original'),
('127.874.d.5.B',3,'A student keeps a notebook of each engine rebuild with dates, parts used, measurements and notes. She is:','["developing and maintaining records appropriate to small engine technology", "skipping notes", "losing data", "avoiding records"]'::jsonb,0,'Records document work.','original'),
('127.874.d.5.B',4,'Which entry would be most useful when revisiting an engine rebuild a year later?','["a joke", "the measurements taken and the parts replaced with dates", "a doodle", "only ''done''"]'::jsonb,1,'Detailed records help later.','original'),
('127.874.d.5.C',3,'A student determines an engine''s displacement by multiplying the cylinder''s bore area by the stroke and by the number of cylinders. She is describing:','["a paint mix", "an unrelated task", "a mathematical formula used for engine calculations", "a random guess"]'::jsonb,2,'Displacement uses geometry.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_126'
from (values
('127.874.d.5.C',4,'If a single-cylinder engine''s bore area is 5 square inches and its stroke is 2 inches, its displacement is:','["7 cubic inches", "3 cubic inches", "25 cubic inches", "10 cubic inches"]'::jsonb,3,'5 × 2 = 10.','original'),
('127.874.d.5.D',3,'A student uses the formula Voltage = Current × Resistance to find how much voltage drops across a resistor in an ignition circuit. She is describing:','["a mathematical formula used for electrical calculations", "a paint formula", "a shipping formula", "a plumbing formula"]'::jsonb,0,'Ohm''s relationship.','original'),
('127.874.d.5.D',4,'A circuit carries 2 amps through a 6 ohm resistor. The voltage across it is:','["0.33 volts", "12 volts", "8 volts", "3 volts"]'::jsonb,1,'2 × 6 = 12.','original'),
('127.874.d.5.E',3,'A technician measures 12 volts across a small engine''s coil and 4 ohms of resistance with a digital multimeter, then predicts the current. She is applying:','["Pascal''s law", "Boyle''s law", "Ohm''s law to a small engine electrical circuit", "Newton''s law"]'::jsonb,2,'I = V ÷ R.','original'),
('127.874.d.5.E',4,'Using Ohm''s law, the current in a circuit with 12 volts and 4 ohms is:','["8 amps", "0.33 amps", "48 amps", "3 amps"]'::jsonb,3,'12 ÷ 4 = 3.','original'),
('127.874.d.6.A',3,'A technician uses email to send a customer a repair estimate and searches the Internet for a discontinued part. She is using:','["personal management software such as email and the Internet", "no software", "only paper", "a hand tool"]'::jsonb,0,'Email and web aid shop work.','original'),
('127.874.d.6.A',4,'Which task is best handled with shop management software?','["tightening a bolt", "tracking customer repair orders and parts inventory", "changing spark plugs", "sharpening a blade"]'::jsonb,1,'Software tracks orders.','original'),
('127.874.d.6.B',3,'A landscaper''s mowers carry a satellite receiver that records where each machine is and how long it ran. This uses:','["a feeler gauge", "a hand crank", "global positioning systems (GPS)", "a tire gauge"]'::jsonb,2,'GPS tracks location.','original'),
('127.874.d.6.B',4,'A geographic information system (GIS) is used to:','["measure valve lash", "mix fuel", "torque bolts", "map and analyze data tied to locations"]'::jsonb,3,'GIS maps location data.','original'),
('127.874.d.6.C',3,'A shop plugs a laptop into an engine''s electronic control unit to read fault codes. This is:','["using computer-based equipment to diagnose an engine", "guessing", "skipping diagnosis", "hand tuning only"]'::jsonb,0,'Scan tools read codes.','original'),
('127.874.d.6.C',4,'A computerized diagnostic tool helps a technician most by:','["replacing safety gear", "reading sensor data and fault codes quickly", "cutting metal", "filling oil"]'::jsonb,1,'Diagnostics speed repair.','original'),
('127.874.d.7.A',3,'A customer asks what a small engine could power at her farm. The technician lists pumps, generators, tillers and mowers, describing:','["only cars", "only boats", "uses and applications of small engines and their components", "no uses"]'::jsonb,2,'Small engines power many tools.','original'),
('127.874.d.7.A',4,'A small engine on a pressure washer drives:','["the wheels of a truck", "the sail", "the lights of a stadium", "the pump that produces high-pressure water"]'::jsonb,3,'The engine powers the pump.','original'),
('127.874.d.7.B',3,'A student identifies the battery, ignition coil, spark plug and kill switch on a mower. She is naming:','["components of electrical-electronic systems", "exhaust parts", "fuel parts only", "cooling parts"]'::jsonb,0,'These are electrical parts.','original'),
('127.874.d.7.B',4,'The part that turns low battery voltage into the high voltage a spark plug needs is the:','["muffler", "ignition coil", "oil dipstick", "air filter"]'::jsonb,1,'Coil steps up voltage.','original'),
('127.874.d.7.C',3,'A technician compares a single-cylinder, vertical-shaft mower engine with a horizontal-shaft tiller engine. He is studying:','["paint colors", "shop layout", "engine designs, components and applications", "tire sizes"]'::jsonb,2,'Designs fit applications.','original'),
('127.874.d.7.C',4,'A vertical-shaft engine is commonly used on a:','["generator only", "wheel tractor only", "boat motor only", "rotary lawn mower"]'::jsonb,3,'Mower blades spin horizontally.','original'),
('127.874.d.7.D',3,'A student uses a micrometer, a dial bore gauge and a compression tester on an engine. These are:','["engine measuring tools and test equipment", "safety signs", "cleaning supplies", "paint tools"]'::jsonb,0,'They measure and test.','original'),
('127.874.d.7.D',4,'A compression tester helps a technician find:','["a loose belt on a truck", "worn rings or leaking valves", "a flat tire", "a dirty windshield"]'::jsonb,1,'Low compression shows wear.','original'),
('127.874.d.7.E',3,'A technician selects a torque wrench, a flywheel puller and a spark plug socket for a tune-up. She is choosing:','["office supplies", "random tools", "tools used for operation, maintenance and repair of small engines", "only hammers"]'::jsonb,2,'Pick tools for the job.','original'),
('127.874.d.7.E',4,'A flywheel puller is used to:','["clean the carburetor", "sharpen blades", "fill the oil", "remove the flywheel without damaging the crankshaft"]'::jsonb,3,'Pullers avoid damage.','original'),
('127.874.d.7.F',3,'A student lists that a two-cycle engine fires every revolution while a four-cycle engine fires every other revolution. She is:','["comparing two-cycle and four-cycle engines", "describing a sail", "describing a diesel", "describing a motor"]'::jsonb,0,'Two-cycle: one power stroke per turn.','original'),
('127.874.d.7.F',4,'A key difference is that a four-cycle engine has a separate:','["muffler cover", "oil sump, so oil is not mixed with the fuel", "gas cap", "spark plug"]'::jsonb,1,'Two-cycles mix oil with fuel.','original'),
('127.874.d.7.G',3,'A student explains that the piston compresses the mixture, the crankshaft turns piston motion into rotation and the camshaft opens the valves. She is explaining:','["shop rules", "filing methods", "the functions of major engine components", "paint choices"]'::jsonb,2,'Each part has a job.','original'),
('127.874.d.7.G',4,'The crankshaft''s main job is to:','["filter air", "cool the exhaust", "store fuel", "convert the piston''s up-and-down motion into rotary motion"]'::jsonb,3,'Linear to rotary.','original'),
('127.874.d.8.A',3,'A mower will not start. The technician checks fuel, spark and compression in order. This is:','["troubleshooting and repairing a small engine", "giving up", "random replacement", "painting the deck"]'::jsonb,0,'Diagnose systematically.','original'),
('127.874.d.8.A',4,'An engine cranks, has fuel and compression, but no spark. The technician should check the:','["blade height", "spark plug, ignition coil and kill-switch wiring", "tire pressure", "fuel cap color"]'::jsonb,1,'Trace the ignition circuit.','original'),
('127.874.d.8.B',3,'A technician mixes gasoline and oil at a ratio of 50 to 1 for a two-cycle trimmer. She is:','["using no oil", "guessing", "using the correct fuel mixture for efficiency and engine life", "using only oil"]'::jsonb,2,'Ratios protect the engine.','original'),
('127.874.d.8.B',4,'Using too little oil in a two-cycle fuel mix can cause:','["longer life", "better lubrication", "cooler running only", "engine damage from poor lubrication"]'::jsonb,3,'Not enough oil scores parts.','original'),
('127.874.d.8.C',3,'A student sets valve lash and uses a timing mark to place the camshaft correctly. She is working on:','["valve arrangement positions and valve timing", "tire rotation", "paint timing", "fuel pricing"]'::jsonb,0,'Valve timing matters.','original'),
('127.874.d.8.C',4,'If the valves open at the wrong time, the engine will:','["run quieter only", "run poorly or not at all", "gain power", "run perfectly"]'::jsonb,1,'Timing controls breathing.','original'),
('127.874.d.8.D',3,'A technician changes the oil, cleans the cooling fins and checks the air filter. He is performing:','["a sales call", "a rebuild", "preventative maintenance of the lubrication and cooling systems", "a paint job"]'::jsonb,2,'Routine care prevents failures.','original'),
('127.874.d.8.D',4,'Clogged cooling fins on an air-cooled engine can cause:','["extra cooling", "better fuel economy", "lower oil use", "overheating and engine damage"]'::jsonb,3,'Fins shed heat.','original'),
('127.874.d.8.E',3,'A technician installs a new spark plug, sets the gap and adjusts the carburetor idle screw. He is doing:','["routine installations, inspections and adjustments", "a full rebuild", "a sale", "a repaint"]'::jsonb,0,'Routine service tasks.','original'),
('127.874.d.8.E',4,'The spark plug gap is set with a:','["caliper only for blades", "wire feeler gauge", "tape measure", "bathroom scale"]'::jsonb,1,'A gauge sets the gap.','original'),
('127.874.d.8.F',3,'A student uses a multimeter, a spark tester and a continuity tester on an ignition system. These are:','["paint tools", "gardening tools", "electrical testing tools for small engines", "cutting tools"]'::jsonb,2,'They test circuits.','original'),
('127.874.d.8.F',4,'A continuity tester shows whether:','["oil is clean", "a tire holds air", "a blade is sharp", "a wire has an unbroken path for current"]'::jsonb,3,'Continuity means a complete path.','original'),
('127.874.d.8.G',3,'A student measures a crankshaft journal with a micrometer and records 1.000 inch. She is using:','["a precision instrument to take measurements", "a scale for weight", "a ruler on a map", "a guess"]'::jsonb,0,'Micrometers measure precisely.','original'),
('127.874.d.8.G',4,'Which tool reads to the nearest thousandth of an inch?','["a tape measure", "an outside micrometer", "a yardstick", "a wooden ruler"]'::jsonb,1,'Micrometers give 0.001 in.','original'),
('127.874.d.8.H',3,'A technician compares a cylinder''s measured bore with the manufacturer''s specification to see if it is worn. He is:','["polishing parts only", "ignoring specs", "inspecting and measuring engine parts for wear tolerances", "painting parts"]'::jsonb,2,'Measure against tolerance.','original'),
('127.874.d.8.H',4,'If a measured piston clearance is greater than the specified limit, the part is:','["better than new", "ready for paint", "perfect", "worn beyond tolerance and should be replaced or reconditioned"]'::jsonb,3,'Out of spec means service.','original'),
('127.874.d.8.I',3,'A student sees that current through a wire creates a magnetic field, and a moving magnet can create current. She is studying:','["the relationship between electric current and magnetic fields", "oil pressure", "air flow", "fuel flow"]'::jsonb,0,'Electromagnetism links them.','original'),
('127.874.d.8.I',4,'A small engine''s magneto makes spark by:','["burning oil", "moving magnets past a coil to induce voltage", "pumping air", "stirring fuel"]'::jsonb,1,'Induction produces voltage.','original'),
('127.874.d.8.J',3,'A technician notes that metal parts expand when hot and shrink when cold, changing clearances in the engine. This describes:','["fuel pricing", "tire wear", "the effects of heating and cooling on small engines", "paint drying"]'::jsonb,2,'Thermal expansion.','original'),
